<?php
namespace App\Http\Controllers;
use App\Models\IssueReturn;use App\Models\Product;use App\Models\Store;use App\Models\StorePosition;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class IssueReturnController extends Controller{public function index():View{$returns=IssueReturn::query()->leftJoin('users as u','issue_returns.returned_by_user_id','=','u.id')->leftJoin('stores','issue_returns.store_id','=','stores.id')->select('issue_returns.*','u.name as returned_by','stores.name as store_name')->withSum('items as total_quantity','quantity')->latest('return_date')->paginate(20);return view('issue-returns.index',compact('returns'));}public function create():View{return view('issue-returns.create',['nextNo'=>$this->next(),'users'=>User::where('is_active',true)->orderBy('name')->get(),'stores'=>Store::where('is_active',true)->orderBy('name')->get(),'positions'=>StorePosition::where('is_active',true)->orderBy('name')->get(),'products'=>Product::where('is_active',true)->orderBy('part_no')->get(['id','part_no','name'])]);}public function store(Request $r){$d=$r->validate(['return_date'=>['required','date'],'returned_by_user_id'=>['nullable','exists:users,id'],'store_id'=>['required','exists:stores,id'],'remarks'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','distinct','exists:products,id'],'items.*.store_position_id'=>['nullable','exists:store_positions,id'],'items.*.quantity'=>['required','numeric','min:.01'],'items.*.chassis_no'=>['nullable','string']]);DB::transaction(function()use($d,$r){$x=IssueReturn::create(collect($d)->except('items')->all()+['return_no'=>$this->next(),'user_id'=>$r->user()->id]);$x->items()->createMany($d['items']);});return redirect()->route('issue-returns.index')->with('success','Issue return saved successfully.');}private function next():string{return 'IRT-'.now()->format('ymd').'-'.str_pad((string)(IssueReturn::whereDate('created_at',now()->toDateString())->count()+1),4,'0',STR_PAD_LEFT);}}
